questionvariables.text:
validate_b4(ex) := block([b,bs,e], e: ev(ex,simp), if is(safe_op(e)="^") then (if is(ev(second(args(e)),simp)=4) then (b: first(args(e)), bs: ev(expand(b),simp), if is(listofvars(bs)=[x]) and is(ev(hipow(bs,x),simp)=1) and integerp(ev(coeff(bs,x,0),simp)) and integerp(ev(coeff(bs,x,1),simp)) and is(ev(coeff(bs,x,0),simp)#0) then "" else "Type a bracket raised to the power 4, with whole numbers in the bracket, for example (5-2*x)^4.") else "Type a bracket raised to the power 4, with whole numbers in the bracket, for example (5-2*x)^4.") else "Type a bracket raised to the power 4, with whole numbers in the bracket, for example (5-2*x)^4.");
/* Design: construct-an-instance pattern (grading checks the property, never a model answer). Source: original. tp 2: 6p^2q^2 = 6m^2, so pq = m or -m; tp 3: 4pq^3 = 4m, so pq^3 = m. */
L: [[2,2,[1,2],[2,1]],[3,8,[8,1],[1,2]],[2,3,[1,3],[3,1]],[3,24,[24,1],[3,2]],[2,4,[1,4],[4,1]],[3,27,[27,1],[1,3]],[2,5,[1,5],[5,1]],[3,16,[16,1],[2,2]],[2,6,[2,3],[6,1]],[3,54,[54,1],[2,3]]];
ix: 1+rand(10);
tp: L[ix][1];
m: L[ix][2];
tg: if tp=2 then 6*m^2 else 4*m;
s1: L[ix][3];
s2: L[ix][4];
samp: (s1[1]+s1[2]*x)^4;
samp2: (s2[1]+s2[2]*x)^4;
dgb: if tp=2 then (1+m^2*x)^4 else (1+m*x)^4;
wrb: (s1[1]+(s1[2]+1)*x)^4;
neg1: (-s1[1]-s1[2]*x)^4;
bstr(p,q) := sconcat("\\left(",p,if q>0 then " + " else " - ",if abs(q)=1 then "" else string(abs(q)),"x\\right)^4");
sampd: bstr(s1[1],s1[2]); samp2d: bstr(s2[1],s2[2]); neg1d: bstr(-s1[1],-s1[2]);
bad3: (s1[1]+s1[2]*x)^3;

feedbackvariables.text:
bs: first(args(ans1));
pp: coeff(expand(bs),x,0);
qq: coeff(expand(bs),x,1);
got: coeff(expand(ans1),x,tp);
dg: if tp=2 then 6*pp*qq else 4*pp*qq;
